contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entrypoint that performs the distinguishing sequence and assertion
    function run(address caller, uint256 sendAmount) public payable {
        // ensure this test harness has enough balance if it needs to send ether to c
        require(address(this).balance >= sendAmount, "insufficient harness balance");

        // fund the target contract c so that any selfdestruct would transfer funds
        // use low-level call to send Ether to c
        (bool ok, ) = address(c).call{value: sendAmount}("");
        require(ok, "funding failed");

        // Observe pre-call balances
        uint256 beforeC = address(c).balance;
        uint256 beforeCaller = caller.balance;

        // Call the potentially-destructive function via a call from an arbitrary caller
        // We simulate the external caller by using a low-level call with specified 'from' is not possible here,
        // so instead we assert the invariant that when msg.sender is not the stored owner, c cannot be destroyed.
        // To check this, we invoke sudicideAnyone() from this contract (which is not the original deployer/owner in general).
        c.sudicideAnyone();

        // Observe post-call balances
        uint256 afterC = address(c).balance;
        uint256 afterCaller = caller.balance;

        // GENERAL RULE: If this caller is not the stored owner then the contract's balance must remain with c
        // We express this by requiring that if the caller's address is not the owner (smartfix_owner getter),
        // then c's balance after the call equals its balance before the call.
        // This captures that only the owner can trigger selfdestruct and drain the funds to msg.sender.
        address owner = c.smartfix_owner();
        assert(owner != caller ? afterC == beforeC : true);
    }

    // Allow the test contract to receive Ether for funding operations
    receive() external payable {}
}

