    uint256 balanceBefore = address(c).balance;

    // attempt to trigger selfdestruct by calling sudicideAnyone from this contract
    // This is the single state-changing call on c in this test
    // We call it regardless of who is the recorded owner; depending on mutant/original it may succeed or revert
    bool didRevert;
    try c.sudicideAnyone() {
      didRevert = false;
    } catch {
      didRevert = true;
    }

    // observe balance of c and this contract after the call
    uint256 balanceAfter = address(c).balance;
