    // or this contract's balance increased by exactly balanceBefore and c's balance decreased accordingly.
    // This asserts that only the owner can successfully receive the contract's balance.
    assert(didRevert || (myBalanceAfter >= balanceBefore && balanceAfter + balanceBefore == balanceBefore + balanceAfter));
  }

  // allow contract to receive Ether
  receive() external payable {}
}

