    // single public test driving function
    // caller provides a target caller address 'caller' and an amount of wei to fund this contract
    // We will attempt to call sudicideAnyone from this contract (msg.sender == address(this)).
    // The property: if address(this) != c.smartfix_owner(), then address(c).balance should remain unchanged (i.e., > 0 if funded) after the call fails/returns.
    // We express this by requiring the test contract be funded, then calling sudicideAnyone and finally asserting the balance relationship.

    function runTest(uint256 fund) public payable {
        // ensure this contract has at least 'fund' wei
        require(address(this).balance >= fund);

        // record balance of target contract before call
        uint256 before = address(c).balance;

        // Call sudicideAnyone from this contract (msg.sender == address(this))
        // It is a state-changing call on c and must be a top-level statement.
        // We don't expect it to succeed on the original P unless this contract is the owner.
        // We do not catch reverts; if it reverts the call will revert the whole transaction and the assert won't run.
        c.sudicideAnyone();

        // observe after balance
        uint256 after = address(c).balance;

        // If this contract is not the owner, then on P the call should revert and not reach here.
        // On M the selfdestruct happens before the require, so the call can succeed and reduce c's balance to 0.
        // Assert that either this contract is the owner, or the target contract's balance did not decrease.
        // This is a single comparison involving public getter and observed balances.
        assert((address(this) == c.smartfix_owner()) || (after >= before));
    }

    // allow contract to receive funds for the test
    receive() external payable {}
