import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: address caller (fuzzer will choose who calls). We must not hard-code owner.
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be meaningful
        vm.assume(caller != address(0));

        // Fund the contract so selfdestruct will send some value
        uint256 funding = 1 ether;
        vm.deal(address(this), funding);
        // send funds to contract
        (bool sent,) = address(c).call{value: funding}("");
        require(sent);

        // Distinguishing behavior depends on who calls sudicideAnyone:
        // If owner calls, both original and mutant will selfdestruct and receiver differences may not manifest.
        // If non-owner calls, require should revert and neither version selfdestructs.
        // The mutant differs when the caller is the owner: the reference sends balance to msg.sender (owner),
        // the mutant sends to smartfix_owner (also owner) — to detect a difference we need a case where smartfix_owner != msg.sender.
        // The contract SmartFix sets smartfix_owner = msg.sender at deployment, which is address(this) in setUp.
        // So to create a difference we must have the owner (smartfix_owner) be some address different from the caller,
        // and the caller must be able to call and pass the require. That means the caller must equal smartfix_owner to pass require.
        // Therefore the only way to trigger the require is when caller == smartfix_owner (the deployer address(this)).
        // To see the mutant redirecting to smartfix_owner rather than msg.sender, we instead detect post-call existence of contract
        // by observing address(c).balance: after successful selfdestruct balance becomes zero. Both versions selfdestruct when owner calls,
        // so we need to detect who received the funds. We can observe that when the owner is a contract (our test contract),
        // selfdestruct sends funds to an address; for the reference it will send to msg.sender (test contract if it calls),
        // for the mutant it will send to smartfix_owner (which was set at deploy time to the deployer address(this)).
        // To make the receiver differ we must cause smartfix_owner != msg.sender during the call: that's impossible because require enforces equality.
        // However, the mutation described changes the target to always be smartfix_owner; the meaningful universal rule we can assert for all inputs is:
        //   After any call to sudicideAnyone by any caller, address(c).balance == 0 if and only if the caller was smartfix_owner (i.e., only owner can destroy).
        // This rule holds in the reference and also in the mutant. But we need a rule that the mutant violates for some input.
        // The subtle difference from the description: mutant changes recipient but still requires owner; we can detect difference by observing which address gained balance.
        // Because the deploy-time smartfix_owner is address(this) (the test contract), we need to simulate a case where msg.sender during call is a different contract that is owner at call time.
        // To do that we deploy a helper contract OwnerCaller that will be set as smartfix_owner by deploying C from that helper.

        // Deploy a helper which deploys its own instance of C so its address is smartfix_owner for that instance.
        OwnerDeployer od = new OwnerDeployer();
        C c2 = od.deployedC();

        // Fund c2 so there is a balance to be forwarded on selfdestruct
        vm.deal(address(this), funding);
        (bool s2,) = address(c2).call{value: funding}("");
        require(s2);

        // Now have the helper contract call sudicideAnyone as its own address (owner). OwnerDeployer will call c2.sudicideAnyone().
        // We capture balances before and after to detect who received funds.
        uint256 beforeOwnerBalance = address(od).balance;
        uint256 beforeTestBalance = address(this).balance;

        // Make the helper perform the call (it will be msg.sender inside c2)
        od.callSuicide();

        uint256 afterOwnerBalance = address(od).balance;
        uint256 afterTestBalance = address(this).balance;

        // In the reference: when OwnerDeployer (owner) calls, selfdestruct should send funds to msg.sender (OwnerDeployer) => its balance increases by funding.
        // In the mutant: selfdestruct sends funds to smartfix_owner which for c2 was set to OwnerDeployer at deployment as well, so still OwnerDeployer.
        // That would make identical behavior. To force a difference we instead use a third-party receiver: deploy a helper that becomes owner at deployment,
        // then have it call sudicideAnyone but via a proxy that causes msg.sender != smartfix_owner. Achieving msg.sender != smartfix_owner while passing require is impossible.
        // Given constraints, the strongest universal property we can check is that only the owner can destroy: after any call, address(c2).balance == 0 iff caller was owner.

        // So the single assertion: if OwnerDeployer called, the contract was destroyed (balance zero). This holds for reference for all inputs and mutant too,
        // but per the problem statement, the mutant redirects payout — however due to deployment patterns both recipient addresses coincide here.
        // We therefore assert the universal property about destruction tied to caller being owner.

        // Determine whether owner call succeeded by checking balance of c2
        bool destroyed = address(c2).balance == 0;
        // owner (od) did call, so destroyed must be true
        assertTrue(destroyed);
    }
}

// Helper that deploys C so its address becomes smartfix_owner for that C instance and then calls sudicideAnyone
contract OwnerDeployer {
    C public deployed;
    constructor() {
        deployed = new C();
    }
    function deployedC() external view returns (C) { return deployed; }
    function callSuicide() external {
        deployed.sudicideAnyone();
    }
}

